.PHONY: docs-status-check
docs-status-check:  ## fail if a PI-gated doc status silently regresses (GATE A must stay PROVISIONAL; AGENTS.md must stay a pointer)
	@! grep -qE '^## Current status.*GATE A CLOSED' ffn_sim/docs/v2_audit/cell_engine/ROLLING_ROADMAP.md || { echo 'DRIFT: ROLLING_ROADMAP asserts "GATE A CLOSED" - GATE A is PROVISIONAL, PI ratification pending (PI_GAP_EVIDENCE_CARDS_2026-07-25.md Card G-A)'; exit 1; }
	@grep -q 'GATE A PROVISIONAL' ffn_sim/docs/v2_audit/cell_engine/ROLLING_ROADMAP.md || { echo 'DRIFT: ROLLING_ROADMAP no longer records GATE A as PROVISIONAL'; exit 1; }
	@grep -qE 'GATE A .*(PROVISIONAL|ratification)' ffn_sim/docs/v2_audit/PI_GAP_EVIDENCE_CARDS_2026-07-25.md || { echo 'DRIFT: GATE A fell off the PI decision queue'; exit 1; }
	@grep -q 'PROVISIONAL' ffn_sim/docs/v2_audit/GATE_A_RESTING_CONVERGENCE_2026-07-23.md || { echo 'DRIFT: GATE A doc no longer carries its PROVISIONAL stamp'; exit 1; }
	@grep -q 'CLAUDE.md' AGENTS.md || { echo 'DRIFT: AGENTS.md no longer points at CLAUDE.md as the single charter'; exit 1; }
	@test "$$(wc -l < AGENTS.md)" -le 40 || { echo 'DRIFT: AGENTS.md re-expanded past 40 lines - it must stay a pointer, not a parallel charter'; exit 1; }
	@! grep -q 'double-count one unified-network filament' AGENTS.md || { echo 'DRIFT: AGENTS.md carries the retired unified-network double-count framing (PI reframed 2026-07-22)'; exit 1; }
	@echo 'docs-status-check: PASS'

